        self.truth_pose = None
        self.truth_pose_received_wall = -math.inf
        self.truth_model_name = str(rospy.get_param(
            "~truth_model_name", "a1_gazebo"))
        # Captured only after a physical ENTRY succeeds.  It lets EXIT use
