        self.first_goal_elapsed = None
        self.exploration_end_elapsed = None
        self.trajectory = []
        self.goal_history = []
        self.path_history = []
        self.scan_history = []
        # SCAN-lite and the portal preflight can ask the voxel mapper about
        # the same footprint several times while one planning transaction is
        # being assembled (simplification, segment audit, then execution
        # waypoint validation).  Cache only exact requests against the
        # current occupancy-grid generation.  A new projection generation
        # therefore invalidates every old answer without weakening any
        # collision or unknown-space decision.
        self._scan_check_cache = {}
        self._scan_check_cache_generation = -1
        self._scan_check_cache_max_entries = max(256, int(rospy.get_param(
            "~scan_check_cache_max_entries", 4096)))
